pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    uint public totalSent;

    function setUp() public { 
        c = new C(); 
        totalSent = 0;
    }

    function testFuzz_property(uint val, uint seed) public {
        val = bound(val, 10, 1000);
        vm.deal(address(this), val);

        // Simulate multiple calls to play()
        for (uint i = 0; i < 3; i++) {
            (bool ok,) = address(c).call{value: 10}("");
            if (ok) {
                totalSent += 10;
            }
        }

        // Last call using the fuzzed value
        (bool ok,) = address(c).call{value: val}("");
        if (ok) {
            totalSent += val;
        }

        // Rule: pot cannot exceed total amount sent to the contract (bank's initial balance is 0)
        assertTrue(c.pot() <= totalSent + address(c).balance - c.pot());
    }
}

