pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 seed) public {
        // Bound seed to simulate different block.timestamp values; 0 and 1 are the critical ones for random % 2
        vm.assume(seed < 2); // seed 0 -> random 0 (win), seed 1 -> random 1 (lose)

        // Set up block state to control random outcome
        // We need block.timestamp and block.difficulty; for deterministic win, set both to even/odd accordingly
        // Since random = uint(keccak256(abi.encodePacked(block.timestamp, block.difficulty))) % 2
        // To force random == 0, we can set block.timestamp=seed and block.difficulty=seed (same parity ensures consistency)
        // But we cannot set block.difficulty easily; we use vm.warp for timestamp and assume difficulty gives the desired outcome
        // Simpler: call play repeatedly until we get a win, but for fuzz we can just call once and track

        // Deal the contract 10 wei
        vm.deal(address(c), 10 ether); // enough balance for transfers
        vm.deal(address(this), 10 ether);

        // Record pot before
        uint potBefore = c.pot();

        // Call play with exactly 10 wei
        (bool success, ) = address(c).call{value: 10}("play()");
        require(success, "play() failed");

        // Read pot after
        uint potAfter = c.pot();

        // Determine if we won: if random == 0, bank got 1 wei and caller got (old pot + 10 - 1) = old pot + 9
        // But we cannot observe random directly; we can infer from balance changes
        // However, we can re-derive: after a win, pot becomes 0; after a loss, pot = potBefore + 10
        // So the rule: potAfter == 0 OR potAfter == potBefore + 10
        assertTrue(potAfter == 0 || potAfter == potBefore + 10);
    }
}

