pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address payable caller, uint randomness) public {
        vm.assume(caller != address(0));

        // Simulate block randomness to force a win (random == 0)
        // We control block.timestamp and block.difficulty to win
        // For a win, we need: uint(keccak256(abi.encodePacked(block.timestamp, block.difficulty))) % 2 == 0
        // We can achieve this by adjusting block.timestamp or block.difficulty
        // Since we just need a 50% chance, we can loop until we get a win
        // But for fuzzing, we can use a different approach: precompute values

        // Actually simpler: we just need to guarantee we get a win for the test
        // We can manipulate the blockhash via vm.warp and vm.difficulty
        // Let's brute-force a combination that gives random == 0

        uint ts = bound(randomness, 1, type(uint).max);
        uint diff = 1;

        // Try up to 1000 times to find values that produce a win
        for (uint i = 0; i < 1000; i++) {
            if (uint(keccak256(abi.encodePacked(ts, diff))) % 2 == 0) {
                vm.warp(ts);
                vm.difficulty(diff);
                break;
            }
            diff++;
        }

        // Ensure we found a winning combination
        vm.assume(uint(keccak256(abi.encodePacked(block.timestamp, block.difficulty))) % 2 == 0);

        // Fund the caller
        uint amount = 10 ether;
        vm.deal(caller, amount);

        // Call play() as the caller
        vm.prank(caller);
        (bool success, ) = address(c).call{value: amount}(abi.encodeWithSignature("play()"));

        // The rule: if the call succeeded (which it does when caller has exact amount), pot must be 0
        assertTrue(c.pot() == 0, "Pot should be zero after a win");
    }
}

